from abc import ABC, abstractmethod

class Animal(ABC):
    def __init__(self, name):
        self.name = name

    @abstractmethod
    def speak(self):
        pass

    @abstractmethod
    def move(self):
        pass

class Dog(Animal):
    def speak(self):
        return f'{self.name} says Woof'

    def move(self):
        return f'{self.name} runs'

class Cat(Animal):
    def speak(self):
        return f'{self.name} says Meow'

    def move(self):
        return f'{self.name} slinks'

class Cow(Animal):
    def speak(self):
        return f'{self.name} says Moo'

    def move(self):
        return f'{self.name} plods'

class UnknownAnimal(Animal):
    def speak(self):
        return f'{self.name} says ...'

    def move(self):
        return f'{self.name} moves'
